#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-30

# strict-mode: opt-out this script inspects commands that are expected to
# fail; `set -e` would turn a missing file into a crash instead of an outcome.
set -uo pipefail

# assert-evidence.sh -- refuse a test verdict that no test run earned (#3263).
#
# /ork:verify once waited ~40 minutes on three backgrounded `npm test` runs
# that had written 0 bytes with no process alive, then produced no verdict at
# all. The contract that prevents a repeat lived in prose; this script is the
# executable form. It looks at the evidence FILE and the process table, and
# names one of five outcomes. Only EVIDENCE may be graded.
#
# USAGE
#   assert-evidence.sh <logfile> [--task-id <id|none>] [--pid <pid>]
#                      [--banner-re <regex>] [--json]
#
#   <logfile>      the file the test command was redirected into
#   --task-id      the harness task id the Bash call returned, or "none"
#                  (recorded, not interpreted)
#   --pid          a process id to test for liveness; when absent, the process
#                  table is searched for a command line containing <logfile>
#   --banner-re    regex proving the RUNNER started; default matches npm's
#                  `> pkg@ver script` line. For pytest use '^=+ test session'
#   --json         one JSON object on stdout instead of key=value
#
# OUTCOMES (exit code, name, condition)
#   0  EVIDENCE           bytes > 0, banner matched, EXIT= marker present
#   1  NO-BANNER          bytes > 0 but the runner's own banner never appeared
#                         (something wrote, the runner did not start), or the
#                         run started and never finished with nobody alive
#   2  usage
#   3  COULD-NOT-OBSERVE  0 bytes and no live process: the run never happened
#   4  STILL-RUNNING      no EXIT= marker yet and a live process exists
#
# The load-bearing rule: a 0-byte file with no process behind it is not
# "pending", it is a failed run, and the absence of the runner's startup
# banner locates the failure BEFORE the runner, not inside it.

LOG=""; TASK_ID="none"; PID=""; BANNER_RE='^> [^ ]+@[^ ]+ '; JSON=0
while [ $# -gt 0 ]; do
  case "$1" in
    --task-id)   TASK_ID="${2:-none}"; shift 2 ;;
    --pid)       PID="${2:-}"; shift 2 ;;
    --banner-re) BANNER_RE="${2:-}"; shift 2 ;;
    --json)      JSON=1; shift ;;
    -h|--help)   awk '/^# assert-evidence.sh/,/^# banner locates the failure/' "$0"; exit 0 ;;
    -*)          printf 'assert-evidence: unknown argument: %s\n' "$1" >&2; exit 2 ;;
    *)           if [ -z "$LOG" ]; then LOG="$1"; shift; else printf 'assert-evidence: unexpected argument: %s\n' "$1" >&2; exit 2; fi ;;
  esac
done

[ -n "$LOG" ] || { printf 'assert-evidence: <logfile> is required\n' >&2; exit 2; }
if [ -n "$PID" ] && ! [[ "$PID" =~ ^[0-9]+$ ]]; then
  printf 'assert-evidence: --pid must be numeric, got %s\n' "$PID" >&2; exit 2
fi

# bytes: a missing file is 0 bytes for this purpose (the run never wrote it)
if [ -f "$LOG" ]; then
  BYTES=$(wc -c < "$LOG" | tr -d ' ')
else
  BYTES=0
fi

BANNER=no; EXIT_MARKER=no
if [ "$BYTES" -gt 0 ]; then
  grep -Eq "$BANNER_RE" "$LOG" && BANNER=yes
  grep -Eq '^EXIT=[0-9]+$' "$LOG" && EXIT_MARKER=yes
fi

# liveness: an explicit pid wins; otherwise search the process table for the
# log path, which the redirection puts on the shell's command line
PID_ALIVE=unknown
if [ -n "$PID" ]; then
  # silent: known-noise -- liveness probe; stderr is "no such process" noise, the exit code is the signal
  if kill -0 "$PID" 2>/dev/null; then PID_ALIVE=yes; else PID_ALIVE=no; fi
else
  rc=0; out=$(pgrep -f -- "$LOG" 2>&1) || rc=$?
  case $rc in
    0) PID_ALIVE=yes ;;
    1) PID_ALIVE=no ;;
    *) PID_ALIVE=unknown ;;   # pgrep denied (sandbox): could not observe the table
  esac
fi

if [ "$BYTES" -eq 0 ]; then
  if [ "$PID_ALIVE" = yes ]; then OUTCOME=STILL-RUNNING; CODE=4
  else OUTCOME=COULD-NOT-OBSERVE; CODE=3
  fi
elif [ "$BANNER" = no ]; then
  OUTCOME=NO-BANNER; CODE=1
elif [ "$EXIT_MARKER" = no ]; then
  if [ "$PID_ALIVE" = yes ]; then OUTCOME=STILL-RUNNING; CODE=4
  else OUTCOME=NO-BANNER; CODE=1   # started, never finished, nobody alive: not gradable
  fi
else
  OUTCOME=EVIDENCE; CODE=0
fi

if [ "$JSON" -eq 1 ]; then
  printf '{"outcome":"%s","bytes":%s,"banner":"%s","exit_marker":"%s","pid_alive":"%s","task_id":"%s","log":"%s"}\n' \
    "$OUTCOME" "$BYTES" "$BANNER" "$EXIT_MARKER" "$PID_ALIVE" "$TASK_ID" "$LOG"
else
  printf 'outcome=%s bytes=%s banner=%s exit_marker=%s pid_alive=%s task_id=%s log=%s\n' \
    "$OUTCOME" "$BYTES" "$BANNER" "$EXIT_MARKER" "$PID_ALIVE" "$TASK_ID" "$LOG"
fi
exit "$CODE"
